class FlightSimulator {
    fun simulateFlight(flyable: Flyable, distance: Double) {
        println("Starting flight simulation for ${flyable.getSpecies()}")
        flyable.fly()
        val speed = flyable.getFlightSpeed()
        val time = if (speed > 0) distance / speed else 0.0
        println("Flight time: $time hours for $distance km")
    }

    fun compareFlightCapabilities(flyables: Array<Flyable>, testDistance: Double) {
        flyables.forEach { flyable ->
            simulateFlight(flyable, testDistance)
            println("---")
        }
    }
}

